import{_ as h,o as t,c as o,a3 as a}from"./chunks/framework.DX_KL3e0.js";const p=JSON.parse('{"title":"Xử lý sự cố","description":"","frontmatter":{},"headers":[],"relativePath":"phu-luc/xu-ly-su-co.md","filePath":"phu-luc/xu-ly-su-co.md","lastUpdated":1782143716000}'),i={name:"phu-luc/xu-ly-su-co.md"};function c(g,n,r,e,l,u){return t(),o("div",null,[...n[0]||(n[0]=[a('<h1 id="xu-ly-su-co" tabindex="-1">Xử lý sự cố <a class="header-anchor" href="#xu-ly-su-co" aria-label="Permalink to &quot;Xử lý sự cố&quot;">​</a></h1><p>Các sự cố thường gặp, trình bày theo mẫu <strong>Triệu chứng → Nguyên nhân → Cách xử lý</strong>. Nếu không tự khắc phục được, liên hệ Admin/IT kèm mô tả chi tiết.</p><h2 id="khong-đang-nhap-đuoc" tabindex="-1">Không đăng nhập được <a class="header-anchor" href="#khong-đang-nhap-đuoc" aria-label="Permalink to &quot;Không đăng nhập được&quot;">​</a></h2><p><strong>Triệu chứng:</strong> nhập email + mật khẩu nhưng không vào được, hoặc báo sai thông tin.</p><p><strong>Nguyên nhân thường gặp:</strong></p><ul><li>Sai email hoặc mật khẩu.</li><li>Tài khoản bị khóa / chưa kích hoạt (<code>status</code> không phải <code>active</code>).</li><li>Quên mật khẩu.</li></ul><p><strong>Cách xử lý:</strong></p><ol><li>Kiểm tra lại email công ty và mật khẩu (chú ý phím Caps Lock).</li><li>Dùng <strong>&quot;Quên mật khẩu?&quot;</strong> để đặt lại qua email.</li><li>Nếu vẫn không được, nhờ Admin kiểm tra trạng thái tài khoản.</li></ol><h2 id="khong-thay-module-menu" tabindex="-1">Không thấy module / menu <a class="header-anchor" href="#khong-thay-module-menu" aria-label="Permalink to &quot;Không thấy module / menu&quot;">​</a></h2><p><strong>Triệu chứng:</strong> thiếu một số mục trong sidebar so với đồng nghiệp.</p><p><strong>Nguyên nhân:</strong> vai trò của bạn chưa được cấp quyền cho module đó (RBAC). Một số mục (như Cấu hình Ticket) chỉ dành cho Super Admin.</p><p><strong>Cách xử lý:</strong> đề nghị Admin/Super Admin cấp quyền module cho vai trò của bạn. Xem <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a>.</p><h2 id="may-cham-cong-khong-đay-du-lieu" tabindex="-1">Máy chấm công không đẩy dữ liệu <a class="header-anchor" href="#may-cham-cong-khong-đay-du-lieu" aria-label="Permalink to &quot;Máy chấm công không đẩy dữ liệu&quot;">​</a></h2><p><strong>Triệu chứng:</strong> máy hiển thị <strong>Offline</strong> trong webapp, bảng công không có dữ liệu mới.</p><p><strong>Nguyên nhân &amp; cách xử lý:</strong></p><ul><li>Máy không ra được Internet → kiểm tra mạng văn phòng, thử truy cập <code>assetflow.fadoai.com</code>.</li><li>Cấu hình sai trên máy → kiểm tra Server Address <code>assetflow.fadoai.com</code>, Path <code>/api/attendance/adms</code>, cổng <code>443</code> (hoặc <code>80</code> với máy không HTTPS).</li><li>Máy đời cũ dùng HTTP nhưng proxy ép redirect HTTPS → nhờ IT mở route HTTP passthrough cho đường dẫn ADMS.</li></ul><h2 id="đa-cham-cong-nhung-du-lieu-khong-hien-thi" tabindex="-1">Đã chấm công nhưng dữ liệu không hiển thị <a class="header-anchor" href="#đa-cham-cong-nhung-du-lieu-khong-hien-thi" aria-label="Permalink to &quot;Đã chấm công nhưng dữ liệu không hiển thị&quot;">​</a></h2><p><strong>Triệu chứng:</strong> máy Online, có chấm công nhưng bảng công của nhân viên trống.</p><p><strong>Nguyên nhân:</strong> mã/PIN trên máy chưa khớp với nhân viên nào (chưa có mapping).</p><p><strong>Cách xử lý:</strong> Admin vào danh sách <strong>mã chưa gán</strong> và gán mã cho đúng nhân viên; hoặc cập nhật <strong>Mã nhân viên</strong> trùng PIN để lần sau tự khớp.</p><h2 id="thong-bao-khong-toi" tabindex="-1">Thông báo không tới <a class="header-anchor" href="#thong-bao-khong-toi" aria-label="Permalink to &quot;Thông báo không tới&quot;">​</a></h2><p><strong>Triệu chứng:</strong> không nhận được thông báo Telegram và/hoặc email.</p><p><strong>Nguyên nhân &amp; cách xử lý:</strong></p><ul><li><strong>Telegram:</strong> chưa liên kết <strong>Telegram Chat ID</strong> trong hồ sơ → liên kết lại. Hoặc bot chưa được cấu hình → báo IT.</li><li><strong>Email:</strong> email vào hộp Spam → kiểm tra Spam. Hoặc dịch vụ gửi email chưa cấu hình → báo IT.</li></ul><h2 id="anh-tep-khong-tai-len-đuoc" tabindex="-1">Ảnh / tệp không tải lên được <a class="header-anchor" href="#anh-tep-khong-tai-len-đuoc" aria-label="Permalink to &quot;Ảnh / tệp không tải lên được&quot;">​</a></h2><p><strong>Triệu chứng:</strong> upload avatar hoặc tệp đính kèm thất bại.</p><p><strong>Nguyên nhân &amp; cách xử lý:</strong></p><ul><li>Tệp quá lớn hoặc sai định dạng → giảm dung lượng / đổi định dạng phù hợp.</li><li>Mạng không ổn định → thử lại.</li><li>Lỗi xử lý ảnh phía server (ví dụ module <code>sharp</code> khi đổi avatar) → báo IT kiểm tra log triển khai.</li></ul><h2 id="app-khong-truy-cap-đuoc" tabindex="-1">App không truy cập được <a class="header-anchor" href="#app-khong-truy-cap-đuoc" aria-label="Permalink to &quot;App không truy cập được&quot;">​</a></h2><p><strong>Triệu chứng:</strong> <code>assetflow.fadoai.com</code> không mở (không trả 200).</p><p><strong>Nguyên nhân:</strong> có thể migration deploy thất bại khiến server không khởi động.</p><p><strong>Cách xử lý (IT):</strong> đọc log deployment trên Coolify tìm dòng <code>❌ FAILED: NNN_*.sql</code> và liên hệ đội kỹ thuật để xử lý migration lỗi.</p>',32)])])}const m=h(i,[["render",c]]);export{p as __pageData,m as default};
